package org.humanjourney.core.mapfeature;
import java.util.*;
/** Pure client mirror; completed immutable snapshots swap atomically, never partial live geometry. */
public final class ClientFeatureState {
 public record Snapshot(FeaturePackets.Header header,Map<String,MapFeature.View> features,FeatureIndex index){public Snapshot{features=Map.copyOf(features);}public int count(){return features.size();}}
 private static final class Pending {final FeaturePackets.Frame[] parts;final FeaturePackets.Frame first;int areaCount,removedCount;long vertices,rings,fragmentBytes;Pending(FeaturePackets.Frame f){first=f;parts=new FeaturePackets.Frame[f.parts()];}boolean complete(){for(var f:parts)if(f==null)return false;return true;}}
 private Snapshot visible=empty(null);private final TreeMap<Long,Pending> pending=new TreeMap<>();private UUID session;private boolean revoked,needsResync;private String problem="";
 private static Snapshot empty(FeaturePackets.Header h){return new Snapshot(h,Map.of(),new FeatureIndex(List.of()));}
 public Snapshot snapshot(){return visible;}public String problem(){return problem;}public boolean needsResync(){return needsResync;}
 private long sequence(){return visible.header()==null?0:visible.header().sequence();}
 public void role(boolean participant){if(!participant){revoked=true;pending.clear();visible=empty(visible.header());}else if(revoked){revoked=false;needsResync=true;}}
 public void clear(){visible=empty(null);pending.clear();session=null;revoked=false;needsResync=false;problem="";}
 private boolean bad(String why){problem=why;needsResync=true;return false;}
 private boolean old(FeaturePackets.Header h){var current=visible.header();return h.sequence()<=sequence()||current!=null&&(h.discovery()<current.discovery()||h.catalog()<current.catalog());}
 public boolean accept(FeaturePackets.Frame f){if(!f.valid())return bad(f.error());var h=f.header();if(session==null)session=h.session();if(!session.equals(h.session())||old(h))return false;if(f.mode()==FeaturePackets.Mode.CLEAR){visible=empty(h);pending.headMap(h.sequence(),true).clear();needsResync=false;problem="";return true;}if(revoked)return bad("Feature transfer received while participant role revoked");var p=pending.computeIfAbsent(h.sequence(),k->new Pending(f));if(!p.first.header().equals(h)||p.first.mode()!=f.mode()||p.first.base()!=f.base()||p.parts.length!=f.parts()){pending.remove(h.sequence());return bad("Inconsistent feature transaction");}if(p.parts[f.part()]!=null){if(!p.parts[f.part()].equals(f)){pending.remove(h.sequence());return bad("Conflicting duplicate feature part");}return false;}p.parts[f.part()]=f;p.areaCount+=f.features().size();p.removedCount+=f.removals().size();for(var v:f.features()){p.vertices+=v.geometry().vertexCount();p.rings+=v.geometry().ringCount();}for(var c:f.fragments())p.fragmentBytes+=c.data().length;if(p.vertices>FeatureGeometry.MAX_CATALOG_VERTICES||p.rings>FeatureGeometry.MAX_CATALOG_RINGS||p.vertices*16+p.rings*8+p.fragmentBytes>FeaturePackets.MAX_TRANSFER_BYTES){pending.remove(h.sequence());return bad("feature staging geometry/byte budget exceeded");}if(p.areaCount>FeaturePackets.MAX_FEATURES||p.removedCount>FeaturePackets.MAX_FEATURES){pending.remove(h.sequence());return bad("Map transaction exceeds total feature limit");}while(pending.size()>2){pending.pollFirstEntry();needsResync=true;}boolean changed=commit(p);boolean progress=true;while(progress){progress=false;for(var entry:new ArrayList<>(pending.entrySet()))if(entry.getValue().complete()&&entry.getValue().first.mode()==FeaturePackets.Mode.DELTA&&entry.getValue().first.base()==sequence()){progress=commit(entry.getValue());changed|=progress;if(progress)break;}}return changed;}
 private boolean commit(Pending p){if(!p.complete())return false;var f=p.first;var h=f.header();if(old(h)){pending.remove(h.sequence());return false;}if(f.mode()==FeaturePackets.Mode.DELTA&&f.base()!=sequence()){if(f.base()<sequence())pending.remove(h.sequence());return bad("Feature delta is missing its exact base; full resync requested");}try{var entries=f.mode()==FeaturePackets.Mode.FULL?new TreeMap<String,MapFeature.View>():new TreeMap<>(visible.features());var added=new HashSet<String>();var removed=new HashSet<String>();var fragments=new ArrayList<FeaturePackets.Fragment>();for(var part:p.parts){fragments.addAll(part.fragments());for(var key:part.removals()){if(!removed.add(key))throw new IllegalArgumentException("duplicate feature removal");entries.remove(key);}for(var area:part.features()){if(!added.add(area.id()))throw new IllegalArgumentException("duplicate feature");entries.put(area.id(),area);}}for(var feature:FeaturePackets.assemble(fragments)){if(!added.add(feature.id()))throw new IllegalArgumentException("duplicate complete/fragmented feature");entries.put(feature.id(),feature);}if(!Collections.disjoint(added,removed))throw new IllegalArgumentException("feature key both removed and updated");if(entries.size()>FeaturePackets.MAX_FEATURES)throw new IllegalArgumentException("feature catalog limit exceeded");GeometryBudget.check(entries.values());var next=new Snapshot(h,entries,new FeatureIndex(entries.values()));visible=next;pending.headMap(h.sequence(),true).clear();needsResync=false;problem="";return true;}catch(IllegalArgumentException e){pending.remove(h.sequence());return bad(e.getMessage());}}
}
